#include <bits/stdc++.h>
using namespace std;

#define length(v) ((int)(v).size())
typedef long long integer;

const int MODULO = 1e9+7;
long long number; int base;

struct MatrixType {
  int matrix[31][31];
  MatrixType operator * (const MatrixType &other) const {
    MatrixType product = {0, };
    for (int i=0; i<=base; i++) {
      for (int j=0; j<=base; j++) {
        product.m[i][j] = 0;
        for (int k=0; k<=base; k++)
          product.m[i][j] = (product.m[i][j] + (long long)m[i][k] * other.m[k][j]) % MODULO;
      }
    }
    return product;
  }
} matricesA[65][30], matricesP[65][30], matricesS[65][30], result;

int main() {
  cin >> number >> base;
  vector<int> digits;
  for (; number; number /= base) digits.push_back(number % base);
  for (int i=0; i<base; i++) {
    for (int j=0; j<=base; j++) matricesA[0][i].m[j][j] = 1;
    for (int j=0; j<=base; j++) matricesA[0][i].m[i][j] = 1;
  }
  for (int i=1; i<(int)digits.size(); i++) {
    matricesP[i-1][0] = matricesA[i-1][0];
    for (int j=1; j<base; j++) matricesP[i-1][j] = matricesP[i-1][j-1] * matricesA[i-1][j];
    matricesS[i-1][base-1] = matricesA[i-1][base-1];
    for (int j=base-1; j--;) matricesS[i-1][j] = matricesA[i-1][j] * matricesS[i-1][j+1];
    for (int j=0; j<base; j++) {
      matricesA[i][j] = matricesS[i-1][j];
      if (j) matricesA[i][j] = matricesA[i][j] * matricesP[i-1][j-1];
    }
  }
  int idx=0;
  for (int i=0; i<=base; i++) result.m[i][i] = 1;
  for (int i=(int)digits.size(); i--;) {
    for (int j=0; j<digits[i]; j++) {
      result = result * matricesA[i][idx];
      idx = (idx+1)%base;
    }
  }
  int total=0;
  for (int i=0; i<=base; i++) total = (total + result.m[i][base]) % MODULO;
  cout << total << endl;
}
